quests[8636] = { id = 8636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Rumblerock", sourceObjective = "Die Dinge des Lebens sind zum Sterben verdammt und kehren zur Erde zurück. Das Geistliche lebt jedoch für immer weiter. Ich wünsche Euch viel Glück, {name}, und bitte, nehmt dies als Zeichen meiner Dankbarkeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[8637] = { id = 8637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stiefel des Todesboten", description = "Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.\n\nBringt mir die Befehlsbindungen der Qiraji, sowie andere geringfügigere Bestandteile und ich werde ein Paar mächtige Stiefel für Euch herstellen.\n\nIhr werdet sie im Kampf gegen den Feind als nützlich empfinden.", sourceObjective = "Bringt die Befehlsbindungen der Qiraji, 2 Götzen des Kampfes, 5 Kristallskarabäen und 5 Knochenskarabäen zu Kandrostrasz in Ahn'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus.", sourceObjectiveStatus = "unverified-source-field" }
quests[8638] = { id = 8638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weste des Todesboten", description = "Der unaussprechliche alte Gott erwacht langsam aus seinem Schlummer unterhalb Ahn'Qirajs. Das schreckliche Schicksal, das Azeroth erwartet, könnte in Tagen oder auch Jahren Wirklichkeit werden, Zeit spielt für Wesen seiner Macht keine Rolle.\n\nStehen die Sterne günstig, wird er furchtbaren Zorn gegen alle Lebewesen walten lassen. Ihr müsst dem zuvorkommen und einen Weg finden, um seiner Existenz ein Ende zu bereiten.\n\nTut dies und bringt mir ein Stück seiner Hülle. Ich werde Euch eine Rüstung gewähren, die noch kein Sterblicher getragen hat... Rüstung für einen Helden, der einen Gott bezwungen hat!", sourceObjective = "Bringt den Knochenpanzer des alten Gottes, 2 Götzen des Kampfes, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Vethsera innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus.", sourceObjectiveStatus = "unverified-source-field" }
quests[8639] = { id = 8639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helm des Todesboten", description = "Die Zwillingsimperatoren... ihr unaufhörliches Flüstern martert langsam meinen Verstand. Sie verhöhnen mich, wissend, dass ich nicht tiefer in ihr Reich vordringen kann, um meinen Bruder Arygos zu retten.\n\nIn meinen Visionen sehe ich ihre monströsen Fratzen, die mit mächtigen Kronen geschmückt sind. Ich werde meine Vergeltung noch bekommen... ich werde diese Symbole der Qirajimacht in solche verwandeln, die unserem Nutzen gerecht werden.\n\nBringt mir die benötigten Bestandteile, {name}. Ich werde Euch dafür ein Kopfstück von unvergleichlicher Macht geben.", sourceObjective = "Bringt Vek'lors Diadem, 2 Götzen des Krieges, 5 Goldskarabäen und 5 Tonskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, {name}?", completion = "Ihr seid erfolgreich gewesen! Das Flüstern der Zwillingsimperatoren ist verstummt.\n\nNehmt dies als Belohnung. Der bloße Anblick hiervon wird Furcht in die Herzen der Qiraji treiben... es soll sie an ihre gefallenen Anführer erinnern und an den Sterblichen, der sie niederstreckte.", sourceObjectiveStatus = "unverified-source-field" }
quests[8640] = { id = 8640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gamaschen des Todesboten", description = "Ihr möchtet Euch also uns gegenüber bewähren, Sterblicher? Nun gut, vielleicht können wir uns ja gegenseitig helfen.\n\nDer uralte Sandwurm, Ouro, ist ein Geschöpf von legendärer Macht. Man sagt, dass er von dem alten Gott selbst als Gespött des Lebens erschaffen wurde.\n\nSeine Haut ist unnatürlich... dick, fast unbezwingbar und dennoch flexibel, was ihm ermöglicht, sich mit der Geschwindigkeit und Grazie eines kleineren Lebewesens zu bewegen.\n\nBringt mir eine Probe seiner Haut, sowie andere geringfügigere Bestandteile und ich werde mächtige Gamaschen für Euch herstellen.", sourceObjective = "Bringt Ouros intakte Haut, 2 Götzen der Nacht, 5 Steinskarabäen und 5 Kristallskarabäen zu Kandrostrasz innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", sourceObjectiveStatus = "unverified-source-field" }
quests[8641] = { id = 8641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiftung des Todesboten", description = "Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.\n\nBringt mir die Bindungen, die von den höchsten Anführern der Qiraji getragen werden und ich werde sie in ein Paar Schulterstücke verarbeiten, die furchteinflößender als die Flügel Nefarians selbst sind!", sourceObjective = "Bringt die Befehlsbindungen der Qiraji, 2 Götzen der Sonne, 5 Silberskarabäen und 5 Tonskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile gesammelt?", completion = "Ich werde diese Schulterstücke aus dem Material, das Ihr mir gebracht habt, und den Schuppen der gefallenen Qirajifeinde herstellen, Sterblicher. Mögen sie Euch den Schutz geben, den Ihr braucht, und möge ihr Anblick unseren Feinden Furcht einflößen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8642] = { id = 8642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Silvervein", sourceObjective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, {name}. Nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[8643] = { id = 8643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Highpeak", sourceObjective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, {name}. Nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
