quests[8696] = { id = 8696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umhang des unsichtbaren Pfads", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, {name}. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, {class}.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.", sourceObjective = "Bringt 1 Hoheitstuch der Qiraji, 2 züngelnde Götzen, 5 Steinskarabäen und 5 Kristallskarabäen zu Keyl Swiftclaw in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir die Materialien für den Umhang gebracht, {name}?", completion = "Ah ja... dieses Tuch ist perfekt.\n\nNehmt diesen Umhang, {name}. Möge er Euch vor der üblen Magie der Qiraji schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8697] = { id = 8697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring der unendlichen Weisheit", description = "Man sagt, dass die Ringe, die von den Lieutenants der Qiraji getragen werden, ungeheuere Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, {class}.", sourceObjective = "Bringt 1 Zeremonienring der Qiraji, 2 Obsidiangötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir den Ring und die Gegenstände besorgt, {name}?", completion = "Ich werde den Edelstein auf dem Ring für Euch austauschen. Ihr werdet sehen, dass der Effekt viel... angenehmer ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[8698] = { id = 8698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring der aufziehenden Stürme", description = "Man sagt, dass die Ringe, die von den Lieutenants der Qiraji getragen werden, ungeheuere Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, {class}.", sourceObjective = "Bringt 1 Gebieterring der Qiraji, 2 Zinnobergötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir den Ring und die Gegenstände besorgt, {name}?", completion = "Ich werde den Edelstein auf dem Ring für Euch austauschen. Ihr werdet sehen, dass der Effekt viel... angenehmer ist.", sourceObjectiveStatus = "unverified-source-field" }
