quests[8725] = { id = 8725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahnin Riversong", sourceObjective = "Der Himmel, mit seinen unzähligen Sternen, bietet die Antworten auf alle irdenen Fragen, {name}. Mag es sein, dass wenn der Weise und Glückliche zu ihnen aufblickt, er die tiefere Wahrheit findet?", sourceObjectiveStatus = "unverified-source-field" }
quests[8726] = { id = 8726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahnin Brightspear", sourceObjective = "Der Himmel, mit seinen unzähligen Sternen, bietet die Antworten auf alle irdenen Fragen, {name}. Mag es sein, dass wenn der Weise und Glückliche zu ihnen aufblickt, er die tiefere Wahrheit findet?", sourceObjectiveStatus = "unverified-source-field" }
quests[8727] = { id = 8727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Farwhisper", sourceObjective = "Der Himmel, mit seinen unzähligen Sternen, bietet die Antworten auf alle irdenen Fragen, {name}. Mag es sein, dass wenn der Weise und Glückliche zu ihnen aufblickt, er die tiefere Wahrheit findet?", sourceObjectiveStatus = "unverified-source-field" }
quests[8728] = { id = 8728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gute und die schlechte Nachricht", description = "Das hat ein wenig länger gedauert als erwartet. Nun lasst mich sehen, was dieses Buch zu berichten hat.\n\n<Leise vor sich hermurmelnd beginnt Narain das Buch zu lesen.>\n\nDie gute Nachricht ist, dass ich mir zu 99% sicher bin, eine Arkanitboje konstruieren zu können, die voll und ganz Euren Anforderungen entspricht. Kommen wir zur schlechten Nachricht: Ich brauche eine gehörige Menge Arkanit, Elementiumerz und Edelsteine.\n\nSobald Ihr mir diese Materialien gebracht habt, kann ich mit der Konstruktion der Boje beginnen.", sourceObjective = "Narain Soothfancy in Tanaris möchte, dass Ihr ihm 20 Arkanitbarren, 10 Elementiumerz, 10 Azerothianische Diamanten und 10 blaue Saphire bringt.", progress = "Arkanitbojen bauen sich nicht einfach von selbst, {name}. Und NEIN, ich werde Euch kein Geld leihen.", completion = "Ein Abmachung ist eine Abmachung. {name}, Ich hoffe nur, Ihr wisst worauf Ihr Euch da einlasst. Das ist 'ne Menge Ärger, für 'nen kleinen Angelausflug.", sourceObjectiveStatus = "unverified-source-field" }
quests[8729] = { id = 8729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn von Neptulon", description = "Hatte ich die schlechte Neuigkeit schon zur Sprache gebracht? Sein Name ist \"Der weiße Riese\": Einhundert Meter Tod und Zerstörung pur. Den kleinen Leckerbissen hatte ich glatt vergessen.\n\nMeinen gnomischen Superpsychokräften nach zu urteilen, befindet sich der beste Ort, um diese Boje zu platzieren, an der Küste Azsharas in der Bucht der Stürme.\n\nHaltet nach einem wirbelnden Maelstrom Ausschau. Vermutlich ist die ganze Gegend mit Wrackteilen übersät.\n\nMacht es gut und nehmt ein paar Freunde mit.\n\nFalls Ihr die ganze Sache wie durch ein Wunder überleben solltet, bringt den Szeptersplitter zu Anachronos.", sourceObjective = "Benutzt die Arkanitboje am wirbelnden Maelstrom in der Bucht der Stürme in Azshara.", progress = "Die Zeit läuft uns davon, großer Held!", completion = "Gut gemacht, {name}. Schon bald werde ich das Szepter der Sandstürme wieder zusammensetzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8730] = { id = 8730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nefarius' Verderbnis", description = "Held, seid Ihr es? Es ist tausend Jahre her, seitdem man mir den Splitter anvertraut hat. Jetzt, in meiner finstersten Stunde soll jemand erscheinen, um mich davon zu entlasten... aber was wäre eine Tragödie ohne Grausamkeit?\n\n<Vaelastrasz hustet geschwächt.>\n\nNe... Nefarius besitzt nun den Szeptersplitter.\n\nDie Zeit ist entscheidend. Nefarius hat vor den Splitter zu zerstören. Ihr müsst Euch beeilen!", sourceObjective = "Tötet Nefarian und bringt den roten Szeptersplitter wieder in Euren Besitz. Bringt den roten Szeptersplitter zu Anachronos in den Höhlen der Zeit in Tanaris. Euch bleiben 5 Stunden, um diese Aufgabe zu erfüllen.", progress = "Wir haben einen weiteren unserer Helden an die Brut von Deathwing verloren. Wir werden für immer zu diesem Leiden verdammt sein...", completion = "Vaelastrasz' Seele beruhigt sich, Held. Die Aspekte verfolgen Eure Fortschritte mit großem Interesse. Wisset, dass Ihr mächtige Verbündete habt.\n\nMir wurde aufgetragen Euch etwas zu geben, das Euch in diesem Kampf helfen soll. Verwendet es weise...", sourceObjectiveStatus = "unverified-source-field" }
quests[8731] = { id = 8731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felddienst", description = "Seid gegrüßt, {name}. Bevor ich Euch mit umfassenderen Aufgaben in diesem Krieg beauftrage, müsst Ihr Euren Anteil am Felddienst leisten.\n\nIhr könnt die Orgrimmarlegion von Captain Skullsplit außerhalb des Regalschwarmbaus finden.\n\nErstattet ihm Bericht und kommt mit dem Beweis für Euren Felddienst zu mir zurück. Ich werde wichtigere Anweisungen für Euch bereithalten.\n\nOh, bitte haltet Euch von der Ironforgebrigade fern. Es herrschen große Spannungen zwischen unseren Freiwilligen der Allianz und der Horde.", sourceObjective = "Erstattet Krug Skullsplit am Posten der Orgrimmarlegion beim Regalschwarmbau Bericht. Bereitet Eure nicht unterzeichneten Felddienstpapiere vor, lasst sie unterzeichnen und bringt sie dann zu Windrufer Kaldon auf Burg Cenarius.\n\nHinweis: das Heilen oder Wirken von begünstigenden Zaubern auf ein Mitglied der Orgrimmarlegion wird Euch für den PvP-Kampf markieren.", progress = "Ihr habt Euren Felddienst geleistet, {name}? Captain Skullsplit hält sich außerhalb des Regalschwarmbaus auf.", completion = "Ich sehe, dass Krug wenig Sinn für Papierkram hat. Er hat das mit Silithidenblut unterzeichtet!\n\nNun gut, {name}. Ich habe eine Reihe von Aufgaben vorbereitet, die Euren Fähigkeiten als {class} gerecht werden sollten.\n\nUnser Feind wird dank der anhaltenden Bemühungen von Euch und Euresgleichen bald zerschmettert werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[8732] = { id = 8732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felddienstpapiere", progress = "Felddienstpapiere? Was für ein Schwachsinn ist das, {name}?", completion = "Früher hätte ich Eure Stirn mit dem Blut unserer gefallenen Feinde gezeichnet, um Eure Taten kenntlich zu machen. Thrall besteht darauf, dass wir den Anliegen der Druiden nachkommen.\n\nHier, nehmt diese Papiere und geht zurück nach Burg Cenarius. Ich bin mir sicher, dass sie dort passende Aufgaben für Euch haben werden." }
quests[8733] = { id = 8733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eranikus, der Tyrann des Traums", description = "Dies ist der Weg der Begleichung, Held. Würde ich heute getötet werden, dann würde ich für den gerechten Zweck sterben. Ihr müsst den grünen Szeptersplitter wiedererlangen. Ihr müsst Eranikus von der Besudelung, die die alten Götter über ihn verhängt haben, reinigen.\n\nReist nach Darnassus. Ihr werdet einen meiner Agenten genau vor den Stadtmauern finden. Dieser Agent wird die Dinge für uns in Bewegung setzen und Tyrande über unsere Pläne informieren, ohne Staghelm zu alarmieren.\n\n<Malfurion seufzt.>\n\nEin Bruch mit der in tausend Jahren geschaffenen Gunst...", sourceObjective = "Reist nach Teldrassil und sucht Malfurions Agenten irgendwo außerhalb der Stadtmauern von Darnassus auf.", completion = "Die Geistergestalt schweigt, man hört lediglich ein leises Summen. Seltsam, aber sie scheint mit Euch über die Gedanken kommunizieren zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8734] = { id = 8734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrande und Remulos", description = "Tyrande wird benachrichtigt, Sterblicher. Shan'do Stormrage hat mich für diesen Fall vorbereitet.\n\nIhr müsst jetzt nach Moonglade reisen und mit Remulos sprechen. Er wird weitere Anweisungen bezüglich der Herbeirufung von Eranikus haben.\n\nWir alle wünschen Euch viel Glück.", sourceObjective = "Reist nach Moonglade und sprecht mit Bewahrer Remulos.", completion = "Es würde unmöglich sein Eranikus aus dem Traum herbeizurufen, wenn er sich weigern sollte. Allerdings erfordern es seine Absichten, dass er unsere Welt betritt. Er will die lebende Manifestation von Malfurion zerstören. Der Erfolg dessen, würde das Ende für einen der mächtigsten Verbündeten des Traums bedeuten. Der Alptraum würde alles Verbleibende ganz und gar zerstören, sollte Malfurion fallen...", sourceObjectiveStatus = "unverified-source-field" }
quests[8735] = { id = 8735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderbnis des Alptraums", description = "Ihr müsst zu den vier Traumportalen von Azeroth reisen und Euch jeweils ein Verderbnisfragment des Alptraums beschaffen. Die Drachkin, die in dieser Gegend hausen, werden derartige Fragmente bei sich tragen. Kommt zu mir zurück, sobald Ihr diese Fragmente eingesammelt habt.", sourceObjective = "Reist zu den vier Portalen des smaragdgrünen Traums in Azeroth und sammelt dort jeweils ein Verderbnisfragment des Alptraums ein. Kehrt zu Bewahrer Remulos in Moonglade zurück, sobald Ihr diese Aufgabe erfüllt habt.", progress = "<Remulos ist tief in Gedanken verloren.>", completion = "Seid Ihr vorbereitet? Ist die Welt auf das vorbereitet, was wir heraufbeschwören werden? Ich weiß es nicht... ich bin Malfurion zum Dienst verpflichtet. Dienst und Ehre...", sourceObjectiveStatus = "unverified-source-field" }
quests[8736] = { id = 8736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Alptraum offenbart sich", description = "Wir müssen gegen Eranikus mit Bedacht vorgehen. Wir sollen ihn erlösen und nicht zerstören.\n\nTyrande ist bereits auf dem Weg, um uns bei dieser Aufgabe zu unterstützen. Wir müssen die Attacken des Drachen überstehen und Nighthaven vor der sicheren Zerstörung bewahren.\n\nSeid auf der Hut! Ihr und Eure Verbündeten seid unsere einzige Hoffnung.", sourceObjective = "Verteidigt Nighthaven gegen Eranikus. Bewahrer Remulos darf dabei nicht ums Leben kommen und Eranikus darf nicht getötet werden. Verteidigt Euch. Erwartet Tyrande.", completion = "Er ist erlöst, {name}. Jetzt kehrt er in den Traum zurück, um zu richten, was er alleine zerstört hat. Eranikus wird ein mächtiger Verbündeter Malfurions und meines Vaters sein.\n\nDiese Rüstungsteile sind für Euch, {name}; Ysera selbst hat sie mir gegeben. Ihr würdet gut daran tun, wenn Ihr sie bei Euren Kämpfen gegen die Qiraji einsetzen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[8737] = { id = 8737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azurblauer Templer", description = "Die Twilight-Hammer und die von ihnen verehrten Elementarfürsten, stellen eine dauerhafte Bedrohung für unsere Operationen in Silithus dar. Trotz der neuen Gegnermassen in Ahn'Qiraj, können wir es uns nicht erlauben, unsere Wachposten und Einsätze gegen den äußeren Feind zu verringern.\n\nFindet einen Weg, um einen azurblauen Templer auf unsere Existenzebene zu beschwören und zerstört ihn.", sourceObjective = "Beschwört und vernichtet einen azurblauen Templer. Erstattet anschließend Bericht bei Bor Wildmane auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz I, um diese Aufgabe abschließen zu können.", progress = "Habt Ihr Eure Aufgabe bereits erfüllt, {name}?", completion = "Ausgezeichnete Arbeit, {name}. Hier ist Euer nächster Auftrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[8738] = { id = 8738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherbericht des Regalschwarms", description = "Wir haben unsere besten Späher bis weit in die Schwarmbauten der Silithiden ausgesendet, um Informationen zu sammeln. Späher Landion hat die Aktivitäten der Silithiden im Regalschwarm nun schon seit Tagen beobachtet. Findet ihn und besorgt Euch einen schriftlichen Bericht. Wir müssen so schnell wie möglich auf diese Informationen reagieren können, {name}.", sourceObjective = "Setzt Euch mit dem cenarischen Späher Landion innerhalb des Regalschwarmbaus in Verbindung und bringt den Späherbericht des Regalschwarms zu Windruferin Proudhorn auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz VII, um diese Aufgabe abschließen zu können.", progress = "Ihr findet Späher Landion innerhalb des Regalschwarmbaus. Beeilt Euch, {name}! Die Zeit spielt eine entscheidende Rolle.", completion = "Eure Bemühungen werden sehr geschätzt, {name}. Ich werde diese Beobachtungen sofort durchsehen, kümmert Euch ruhig schon um Eure nächste Aufgabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[8739] = { id = 8739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherbericht des Ashischwarms", description = "Wir haben unsere besten Späher bis weit in die Schwarmbauten der Silithiden ausgesendet. Späherin Jalia hat die Aktivitäten der Silithiden im Ashischwarm nun schon seit Tagen beobachtet. Findet sie und besorgt Euch einen schriftlichen Bericht. Wir müssen so schnell wie möglich auf diese Informationen reagieren können, {name}.", sourceObjective = "Setzt Euch mit der cenarischen Späherin Jalia innerhalb des Ashischwarmbaus in Verbindung und bringt den Späherbericht des Ashischwarms zu Windruferin Proudhorn auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz VIII, um diese Aufgabe abschließen zu können.", progress = "Ihr findet Späherin Jalia innerhalb des Ashischwarmbaus. Beeilt Euch, {name}! Die Zeit spielt eine entscheidende Rolle.", completion = "Eure Bemühungen werden sehr geschätzt, {name}. Ich werde diese Beobachtungen sofort durchsehen, kümmert Euch ruhig schon um Eure nächste Aufgabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[8740] = { id = 8740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marodeure der Twilight", description = "Es wurden mehrfach berittene Gruppen der Twilight-Hammer gesichtet, die außerhalb der Reichweite unserer Truppen in Burg Cenarius, kleinere Patrouillen und Karawanen angreifen. Findet und vernichtet die Marodeure der Twilight, gemeinsam mit ihrem Anführer, einem furchterregenden Krieger namens Morna. Meldet Euch anschließend bei Windruferin Proudhorn.", sourceObjective = "Tötet den Marodeur der Twilight Morna und 5 Marodeure der Twilight. Erstattet anschließend Bericht bei Windruferin Proudhorn. Ihr benötigt auch den taktischen Einsatz IX, um diese Aufgabe abschließen zu können.", progress = "Habt Ihr Eure Aufgabe bereits erfüllt, {name}?", completion = "Gut gemacht, {name}. Die Marodeure der Twilight haben unseren Patroullien ganz schöne Verluste beschert. Hier ist Euer nächster Auftrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[8741] = { id = 8741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Held kehrt zurück", description = "Der Bewahrer erwartet Eure Rückkehr, {name}. Bringt den grünen Szeptersplitter zu Anachronos in den Höhlen der Zeit.", sourceObjective = "Bringt den grünen Szeptersplitter zu Anachronos in den Höhlen der Zeit.", progress = "<Anachronos nickt.>", completion = "Jeder wird von Euren Taten erfahren, Held. Man wird Loblieder von Orgrimmar bis weit in den südlichen Meeren singen. Jeder wird den Held des Bronzeschwarms kennen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8742] = { id = 8742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht von Kalimdor", sourceObjective = "Eintausend Jahre sind vergangen und wie es vorausgesagt wurde, steht die Eine nun vor mir. die Auserwählte, welche Ihr Volk in ein neues Zeitalter führen wird. Spürt Ihr es? Der alte Gott erzittert, {name}! Oh ja, er fürchtet Eure Bestimmung. Zerschlagt die Prophezeiung von C'thun!\n\nEr weiß, dass Ihr zu ihm kommen werdet - und mit Euch kommt die Macht von Kalimdor. Lasst es mich wissen, wenn Ihr bereit seid und ich werde Euch das Szepter der Sandstürme anvertrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8743] = { id = 8743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagt den Gong!", progress = "Die Oberfläche des Skarabäusgongs spiegelt bedrohlich das Licht der sengenden Sonne Silithus' wieder. Stählt Euch für das Kommende, denn wurde der Gong erst einmal geschlagen, werden sich die Tore nach Ahn'Qiraj öffnen. Dann wird es kein Zurück mehr geben\n\nIm züngelnden Antlitz der Bestie lauert nur Chaos und Zerstörung. Verteidigt Euer Volk!", completion = "Aus dem Erdreich vor dem Gong gräbt sich ein besonderer Kristall an die Oberfläche empor. Möglicherweise ein Geschenk der Brut." }
quests[8744] = { id = 8744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein sorgfältig verpacktes Geschenk", sourceObjective = "Auf dem Kärtchen and diesem Geschenk steht:\n\nAn {name},\n\nmöge Euer Winterfest fröhlich und heiter verlaufen!", sourceObjectiveStatus = "unverified-source-field" }
quests[8745] = { id = 8745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz des Zeitlosen", sourceObjective = "Seig gegrüßt, großer Held! Ich bin Jonathan, der Bewahrer des heiligen Gongs und ewige Wächter des bronzenen Drachenschwarms.\n\nDer Zeitlose hat mich dazu ermächtigt, Euch aus seinem Schatz einen Gegenstand Eurer Wahl zu gewähren. Möge er Euren Kampf gegen C'Thun erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[8746] = { id = 8746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metzen das Rentier", description = "Es ist eine KATASTROPHE! Metzen das Rentier wurde entführt!\n\nMetzen ist eines von Altvater Winters acht Rentieren - und Eigentum von Kokelwälder. Wir haben nicht nur einen, sondern ZWEI Erpresserbriefe von Gruppen erhalten. Beide behaupten, Metzen in ihrer Gewalt zu haben. Gerade jetzt zur Festtagszeit haben wir hier ein echtes Problem. Bitte findet Metzen und bringt ihn zurück!\n\nSchaut Euch die Erpresserbriefe an, vielleicht findet Ihr darin ja Hinweise. Streut diesen Rentierstaub über ihn, wenn Ihr ihn findet, er wird ihn aus sämtlichen Fesseln befreien!\n\nBitte, beeilt Euch!", sourceObjective = "Findet Metzen das Rentier. Lest Euch die erhaltenen Notizen durch, um Tipps über seinen Aufenthaltsort zu erhalten.\n\nWenn Ihr Metzen findet, solltet Ihr den Beutel mit Rentierstaub dabeihaben. Berieselt Ihr Metzen mit dem Staub, sollte dies ihn aus seiner Gefangenschaft befreien.\n\nBringt den Beutel zu Kaymard Copperpinch in Orgrimmar zurück, sobald Ihr Metzen befreit habt.", progress = "{name}! Habt Ihr ihn gefunden? Konntet Ihr den Notizen, die ich Euch mitgegeben habe, genug Informationen entnehmen, um ihn ausfindig zu machen? Mir wird ganz schlecht wenn ich daran denke, was diese fiesen Strolche ihm antun könnten… Ein so hohes Lösegeld können wir uns einfach nicht leisten.", completion = "Ihr habt es geschafft! Hurra!\n\nMetzen ist gerade eben erst zurück zu den Ställen von Altvater Winter geflogen. Ja, Metzen kann wirklich fliegen! Der Staub hat ganze Arbeit geleistet, ich wusste, das würde funktionieren. Ihr habt das Winterhauchfest und Kokelwälder vor dem Untergang bewahrt. Danke, {name}.\n\nHört mal, weil Ihr das für uns getan habt, möchte ich Euch das hier geben. Das ist etwas GANZ Besonderes. Wenn Ihr ein Reittier habt, werdet Ihr bestimmt eine Menge Spaß damit haben. Frohes Winterhauchfest!", sourceObjectiveStatus = "unverified-source-field" }
quests[8747] = { id = 8747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Beschützers", sourceObjective = "Beeindruckend, kleine Kreatur. Ihr habt eine Menge durchgemacht, um das Vertrauen des bronzenen Drachenschwarms zu erwerben. Eure Hingabe und Selbstaufopferung wurde zur Kenntnis genommen.\n\nDer Siegelring des Beschützers birgt enorme Kräfte in sich, die Euch gegen die Mächte des Bösen helfen werden. Seine Macht wird Eure Verteidigungskraft um ein Vielfaches verstärken.\n\nAber seid gewarnt! Habt Ihr erst einmal Euren Pfad gewählt, gibt es kein Zurück mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[8748] = { id = 8748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Beschützers", progress = "Eure selbstlosen Bemühungen, die Kinder Kalimdors zu verteidigen, wurden zur Kenntnis genommen. Übergebt mir Euren Siegelring, damit ich seine Kräfte verstärken kann.", completion = "Euer Aufstieg innerhalb der Brut ist mehr als beachtlich, {name}. Möget Ihr niemals vom Pfad des Beschützers abkommen!" }
quests[8749] = { id = 8749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Beschützers", progress = "Ihr ehrt meinesgleichen, {name}! Vernichtet die Feinde Kalimdors! Zeigt ihnen, was es heißt, das Land des ewigen Sternenlichts anzugreifen.\n\nIhr habt Euch eine weitere Verstärkung des Rings verdient. Übergebt mir Euren Siegelring, damit ich seine Kräfte erweitern kann.", completion = "Euer Aufstieg innerhalb der Brut ist mehr als beachtlich, {name}. Möget Ihr niemals vom Pfad des Beschützers abkommen!" }
quests[8750] = { id = 8750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Beschützers", progress = "Eine derartige Hingabe für eine gerechte Sache ist selten. Ihr habt die Unbeugsamkeit Eures Willens bewiesen, {name}! Dafür, dass Euer wacher Geist und Euer scharfer Verstand über diese Welt wacht, sollt Ihr reichhaltig belohnt werden.\n\nÜbergebt mir Euren Siegelring, damit ich seine Kräfte verstärken kann.", completion = "Euer Aufstieg innerhalb der Brut ist mehr als beachtlich, {name}. Möget Ihr niemals vom Pfad des Beschützers abkommen!" }
quests[8751] = { id = 8751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beschützer von Kalimdor", progress = "Selten habe ich solch eine Hingabe, solch ein Durchhaltevermögen gesehen! Der bronzene Drachenschwarm gewährt Euch die mächtigste Verzauberung. Der Zeitlose selbst, hat es befohlen!\n\nÜbergebt mir Euren Siegelring, damit ich seine Kräfte verstärken kann.", completion = "Erhebt Euch, Beschützer von Kalimdor! Zeigt Euch und lasst Euch huldigen!" }
quests[8752] = { id = 8752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Eroberers", sourceObjective = "Beeindruckend, kleine Kreatur. Ihr habt eine Menge durchgemacht, um das Vertrauen des bronzenen Drachenschwarms zu erwerben. Eure Hingabe und Selbstaufopferung wurde zur Kenntnis genommen.\n\nDer Siegelring des Eroberers birgt enorme Kräfte in sich, die Euch gegen die Mächte des Bösen helfen werden. Seine Macht wird Eure physischen Angriffe um ein Vielfaches verstärken.\n\nAber seid gewarnt! Habt Ihr erst einmal Euren Pfad gewählt, gibt es kein Zurück mehr.", sourceObjectiveStatus = "unverified-source-field" }
