quests[8762] = { id = 8762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metzen das Rentier", description = "Es ist eine KATASTROPHE! Metzen das Rentier wurde entführt!\n\nMetzen ist eines von Altvater Winters acht Rentieren - und Eigentum von Kokelwälder. Wir haben nicht nur einen, sondern ZWEI Erpresserbriefe von Gruppen erhalten. Beide behaupten, Metzen in ihrer Gewalt zu haben. Gerade jetzt zur Festtagszeit haben wir hier ein echtes Problem. Bitte findet Metzen und bringt ihn zurück!\n\nSchaut Euch die Erpresserbriefe an, vielleicht findet Ihr darin ja Hinweise. Streut diesen Rentierstaub über ihn, wenn Ihr ihn findet, er wird ihn aus sämtlichen Fesseln befreien!\n\nBitte, beeilt Euch!", sourceObjective = "Findet Metzen das Rentier. Lest Euch die erhaltenen Notizen durch, um Tipps über seinen Aufenthaltsort zu erhalten.\n\nWenn Ihr Metzen findet, solltet Ihr den Beutel mit Rentierstaub dabeihaben. Berieselt Ihr Metzen mit dem Staub, sollte dies ihn aus seiner Gefangenschaft befreien.\n\nBringt den Beutel zu Wulmort Jinglepocket in Ironforge zurück, sobald Ihr Metzen befreit habt.", progress = "{name}! Habt Ihr ihn gefunden? Konntet Ihr den Notizen, die ich Euch mitgegeben habe, genug Informationen entnehmen, um ihn ausfindig zu machen? Mir wird ganz schlecht wenn ich daran denke, was diese fiesen Strolche ihm antun könnten… Ein so hohes Lösegeld können wir uns einfach nicht leisten.", completion = "Ihr habt es geschafft! Hurra!\n\nMetzen ist gerade eben erst zurück zu den Ställen von Altvater Winter geflogen. Ja, Metzen kann wirklich fliegen! Der Staub hat ganze Arbeit geleistet, ich wusste, das würde funktionieren. Ihr habt das Winterhauchfest und Kokelwälder vor dem Untergang bewahrt. Danke, {name}.\n\nHört mal, weil Ihr das für uns getan habt, möchte ich Euch das hier geben. Das ist etwas GANZ Besonderes. Wenn Ihr ein Reittier habt, werdet Ihr bestimmt eine Menge Spaß damit haben. Frohes Winterhauchfest!", sourceObjectiveStatus = "unverified-source-field" }
quests[8763] = { id = 8763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Held des Tages", description = "Eigentlich darf ich Euch das gar nicht sagen, aber da Ihr ja der Held des Tages seid, mach ich mal 'ne Ausnahme.\n\nUm diese Jahreszeit gibt es überall frische Tannenzweige, aber die Zweige bleiben nicht lange frisch. Wir haben eine Maschine, die Tannenzweige konserviert - die bleiben dann für immer frisch! Wir benutzen sie um die Festtage etwas aufzupeppen... und unsere Profite im Sommer zu steigern!\n\nIch lasse Euch den Konservierer benutzen, aber nur, wenn Ihr ein Meisterkoch seid. Ihr werdet etwas Tiefsteinsalz und etwa zwei, drei, ach, sagen wir einfach fünf Goldstücke brauchen. Damit solltet Ihr ein nettes Bündel konservieren können, das Ihr behalten könnt.", sourceObjective = "Bringt 1 Tiefsteinsalz und 5 Goldstücke zum Tannenzweigkonservierer. Ihr werdet 5 konservierte Tannenzweige erhalten.", progress = "Der Tannenzweigkonservierer sieht auf den ersten Blick wie eine Art Destillierapparat aus, bei genauerer Betrachtung werden allerdings einige goblinartige Veränderungen offensichtlich. Eure Fähigkeiten in der Kochkunst erlauben es Euch allerdings zu verstehen, wie die Maschine funktioniert.\n\nEs sind schon frische Tannenzweige in der Maschine - Ihr müsst nur noch Tiefsteinsalz dazugeben und fünf Goldstücke einwerfen, um sie ans Laufen zu bringen.", completion = "Die Maschine fängt an zu rumpeln und Dampf auszuspeien, während sie mit der Arbeit beginnt. Schon kurz darauf ist sie fertig. Sie spuckt noch etwas Dampf aus und eine Klappe öffnet sich. In der Öffnung befindet sich ein Bündel konservierter Tannenzweige.", sourceObjectiveStatus = "unverified-source-field" }
quests[8764] = { id = 8764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Pfad wechseln - Kein Beschützer mehr" }
quests[8765] = { id = 8765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Pfad wechseln - Kein Herbeirufer mehr" }
quests[8766] = { id = 8766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Pfad wechseln - Kein Eroberer mehr" }
quests[8767] = { id = 8767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein leicht geschütteltes Geschenk", sourceObjective = "Dieses Geschenk sieht aus, als wäre es schon ein paar Mal geschüttelt worden. Auf dem Kärtchen steht:B\nFür {name}, einen ganz besonderen Helden.", sourceObjectiveStatus = "unverified-source-field" }
quests[8768] = { id = 8768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein fröhlich verpacktes Geschenk", sourceObjective = "Auf diesem festlich verpackten Geschenk steht Euer Name!\n\n Hat sich das etwa gerade bewegt?", sourceObjectiveStatus = "unverified-source-field" }
quests[8769] = { id = 8769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein tickendes Geschenk", sourceObjective = "Ein wundervolles Winterhauchfest wünschen Euch Eure Freunde bei Kokelwälder.", sourceObjectiveStatus = "unverified-source-field" }
quests[8770] = { id = 8770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Verteidiger des Ashischwarms", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Ashischwarms teilzunehmen. Eure Hauptziele sind die Verteidiger des Ashischwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Verteidiger des Ashischwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz I, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas, das Ihr mir erzählen wollt, {class}?", completion = "Ausgezeichnete Arbeit, {name}. Euer Eifer ist bemerkenswert!", sourceObjectiveStatus = "unverified-source-field" }
quests[8771] = { id = 8771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Sandpirscher des Ashischwarms", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Ashischwarms teilzunehmen. Eure Hauptziele sind die Sandpirscher des Ashischwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Sandpirscher des Ashischwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz II, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas, das Ihr mir erzählen wollt, {class}?", completion = "Exzellente Arbeit, {name}. Eure Leistungen beim Angriff auf den Bau des Ashischwarms wurden zur Kenntnis genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8772] = { id = 8772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Wegbehüter des Zoraschwarms", description = "Es wurde Verstärkung für den Angriff auf den Bau des Zoraschwarms angefordert. Man hat Euch ausgewählt, um die Wegbehüter des Zoraschwarms anzugreifen. Erstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Wegbehüter des Zoraschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz VI, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas, das Ihr mir erzählen wollt, {class}?", completion = "Exzellente Arbeit, {name}. Eure Leistungen beim Angriff auf den Bau des Zoraschwarms wurden zur Kenntnis genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8773] = { id = 8773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Häscher des Zoraschwarms", description = "Es wurde Verstärkung für den Angriff auf den Bau des Zoraschwarms angefordert. Man hat Euch ausgewählt, um die Häscher des Zoraschwarms anzugreifen. Erstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Häscher des Zoraschwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz IV, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas, das Ihr mir erzählen wollt, {class}?", completion = "Ausgezeichnete Arbeit, {name}. Ich habe nur Gutes über Eure Teilnahme an dem Angriff gegen den Zoraschwarm gehört. Macht so weiter und der Sieg wird schon bald unser sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[8774] = { id = 8774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Wegelagerer des Regalschwarms", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt, je weiter die Kriegsvorbereitungen voranschreiten, eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Regalschwarms teilzunehmen. Eure Hauptziele sind die Wegelagerer des Regalschwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Wegelagerer des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz VIII, um diese Aufgabe abschließen zu können.", progress = "Ihr wollt mir etwas mitteilen, {name}?", completion = "Exzellente Arbeit, {name}. Eure Leistungen beim Angriff auf den Bau des Regalschwarms wurden zur Kenntnis genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8775] = { id = 8775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Feuerspucker des Regalschwarms", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Regalschwarms teilzunehmen. Eure Hauptziele sind die Feuerspucker des Regalschwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Feuerspucker des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz IX, um diese Aufgabe abschließen zu können.", progress = "Ihr wollt mir etwas mitteilen, {name}?", completion = "Exzellente Arbeit, {name}. Eure Leistungen beim Angriff auf den Bau des Regalschwarms wurden zur Kenntnis genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8776] = { id = 8776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Sklavenjäger des Regalschwarms", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt, je weiter die Kriegsvorbereitungen voranschreiten, eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Regalschwarms teilzunehmen. Eure Hauptziele sind die Sklavenjäger des Regalschwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Sklavenjäger des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz X, um diese Aufgabe abschließen zu können.", progress = "Ihr wollt mir etwas mitteilen, {name}?", completion = "Exzellente Arbeit, {name}. Eure Leistungen beim Angriff auf den Bau des Regalschwarms wurden zur Kenntnis genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8777] = { id = 8777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Einbuddler des Regalschwarms", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Regalschwarms teilzunehmen. Eure Hauptziele sind die Einbuddler des Regalschwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Einbuddler des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz XI, um diese Aufgabe abschließen zu können.", progress = "Ihr wollt mir etwas mitteilen, {name}?", completion = "Exzellente Arbeit, {name}. Eure Leistungen beim Angriff auf den Bau des Regalschwarms wurden zur Kenntnis genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8778] = { id = 8778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ironforgebrigade braucht Sprengstoff!", description = "Uns liegt eine Anforderung der Ironforgebrigade vor, die eine Menge… na sagen wir, recht explosive Komponenten umfasst. Beschafft diese Komponenten und bringt sie zu einem Kerl namens Nozzlespring, einem Mitglied der Ironforgebrigade.", sourceObjective = "Bringt Arkanist Nozzlespring nahe des Zoraschwarmbaus in Silithus 6 Öle des Feuerbrandes, 5 Einheiten Goblin-Raketentreibstoff und 10 Einheiten dichtes Sprengpulver. Ihr benötigt auch Logistikeinsatz IV, um diese Aufgabe abschließen zu können.", progress = "Habt Ihr die Materialien, {name}?", completion = "Ah, sehr gut. Das kommt mir alles sehr gelegen! Ich muss Euch danken, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[8779] = { id = 8779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Materialien", description = "Geologin Larksbanes Studien haben sich für unsere Operationen in Silithus als sehr wertvoll erwiesen. Vor kurzem hat sie eine Ladung magischer Materialien angefordert, die sie für ihre weiteren Forschungen dringend benötigt.\n\nBeschafft die notwendigen Materialien und liefert sie direkt an sie aus, damit Geologin Larksbane ihre Forschungen ungestört fortsetzen kann.", sourceObjective = "Bringt 1 großen glänzenden Splitter, 1 großen strahlenden Splitter und einen gewaltigen Smaragd zu Geologin Larksbane auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz V, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich, {name}?", completion = "Ah, diese hier sind mir von großem Nutzen! Wisst Ihr {name}, in dieser Wüste ist es sehr schwer an derartige Materialien zu kommen. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[8780] = { id = 8780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rüstungssets für den Feldeinsatz", description = "Der Ironforgebrigade gehen im Feld die Rüstungssets aus. Schnappt Euch eine Ladung und bringt sie zu Janela Stouthammer am Posten der Ironforgebrigade beim Zoraschwarmbau.", sourceObjective = "Bringt 8 unverwüstliche Rüstungssets und 8 schwere Rüstungsset zu Janela Stouthammer am Posten der Ironforgebrigade beim Zoraschwarmbau in Silithus. Ihr benötigt auch Logistikeinsatz VII, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich, {name}?", completion = "Vielen Dank, ich werde alles direkt an unsere Truppen ausgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[8781] = { id = 8781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen für den Feldeinsatz", description = "Die Ironforgebrigade hat sich in den Kämpfen von Silithus als ein würdiger Verbündeter erwiesen. Unglücklicherweise hat sie auf dem Weg hierher die meisten ihrer Vorräte eingebüßt. Beschafft eine Ladung Waffen und bringt sie zu Janela Stouthammer nahe des Baus des Zoraschwarms.", sourceObjective = "Bringt 2 Mondstahlbreitschwerter zu Janela Stouthammer am Posten der Ironforgebrigade beim Zoraschwarmbau. Ihr benötigt auch Logistikeinsatz VI, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich, {name}?", completion = "Oh, fantastisch! Endlich muss ich mir kein Gemaule über stumpfe Waffen mehr anhören. Vielen Dank, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[8782] = { id = 8782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uniformnachschub", description = "Die letzte Ladung neuer Rekruten hat uns einen Engpass an Uniformen beschert. Beschafft uns eine Ladung Schneiderwaren, damit wir mehr Uniformen herstellen können. Bringt alles zur Windruferin Proudhorn.", sourceObjective = "Bringt 1 Einheit Mondstoff, 2 Runenstoffballen und 1 Einheit Eisenweberseide zu Windruferin Proudhorn auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz VIII, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich, {name}?", completion = "Ah, genau was wir jetzt brauchen. Wir wissen Eure Arbeit sehr zu schätzen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8783] = { id = 8783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besondere Materialien", description = "Vargus, der Schmied von Burg Cenarius, hat verzauberte Materialien zur Herstellung von stärkeren Waffen angefordert. Beschafft die benötigten Materialien und bringt sie direkt zu Vargus, um den hohen Ausrüstungsstand unserer Truppen auf Burg Cenarius aufrechtzuerhalten.", sourceObjective = "Bringt Vargus auf Burg Cenarius in Silithus 2 verzauberte Thoriumbarren und 2 Einheiten verzaubertes Leder. Ihr benötigt auch Logistikeinsatz IX, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich, {name}?", completion = "Ah, sehr gut. Dieses Material ist von hervorragender Qualität. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8784] = { id = 8784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Qiraji", description = "Ihr habt ein uraltes Artefakt der Qiraji entdeckt! Vielleicht interessiert sich einer der Drachen am Eingang des Tempels für dieses Relikt.", sourceObjective = "Bringt das uralte Qirajiartefakt zu den Drachen, die sich nahe des Tempeleingangs versteckt halten.", progress = "Ihr glüht! Ich weiß, was das bedeutet…", completion = "Ein einmaliger Fund, {name}. Einfach fantastisch! Mit Hilfe dieses Artefakts, erhalten wir sicherlich einen Einblick in die verquerte Denkensweise des Feindes.", sourceObjectiveStatus = "unverified-source-field" }
quests[8785] = { id = 8785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Orgrimmarlegion braucht Mojo!", description = "Uns liegt eine Anforderung der Orgrimmarlegion vor, die eine Menge recht ungewöhnliche Materialien umfasst. Aber in Anbetracht ihrer jüngsten Leistungen in Silithus, möchten wir dieser Anfrage so schnell wie möglich nachkommen. Beschafft die notwendigen Materialien und bringt sie einer Trollfrau namens Shai.", sourceObjective = "Bringt Schattenpriesterin Shai nahe des Regalschwarmbaus in Silithus 6 Einheiten mächtiges Mojo, 6 Fläschchen großes Mojo und 8 Öle des Feuerbrandes. Ihr benötigt auch Logistikeinsatz IV, um diese Aufgabe abschließen zu können.", progress = "Habt Ihr die Materialien, {name}?", completion = "Ah, sehr gut. Genau, was ich gebraucht habe. Aus diesen Zutaten werde ich ein ganz spezielles Gebräu mischen. Den Silithiden wird es bestimmt nicht gut bekommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[8786] = { id = 8786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen für den Feldeinsatz", description = "Die Orgrimmarlegion hatte bereits vor einiger Zeit zusätzliche Waffen angefordert, die wir bisher noch nicht liefern konnten. Beschafft die notwendigen Waffen und bringt sie zu Merok Longstride außerhalb des Regalschwarmbaus.", sourceObjective = "Bring 3 massive Eisenäxte zu Merok Longstride im Lager der Orgrimmarlegion außerhalb des Regalschwarmbaus. Ihr benötigt auch Logistikeinsatz VI, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich, {name}?", completion = "Ausgezeichnete Arbeit. Unsere Vorräte gingen gerade zur Neige, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8787] = { id = 8787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rüstungssets für den Feldeinsatz", description = "Die Orgrimmarlegion ist zu unserer Unterstützung in Silithus eingetroffen. Unglücklicherweise hat sie auf dem Weg hierher die meisten ihrer Rüsstungssets eingebüßt. Beschafft eine Ladung und bringt sie zu Merok Longstride im Lager der Orgrimmarlegion.", sourceObjective = "Bringt 8 unverwüstliche Rüstungssets und 8 schwere Rüstungsset zu Merok Longstride nahe des Regalschwarmbaus. Ihr benötigt auch Logistikeinsatz VII, um diese Aufgabe abschließen zu können.", progress = "Ihr habt etwas für mich, {name}?", completion = "Ah, ja… Ich werde alles direkt an die Truppe ausgeben, {name}. Die Orgrimmarlegion ist Euch zu Dank verpflichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[8788] = { id = 8788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein leicht geschütteltes Geschenk", sourceObjective = "Dieses Geschenk sieht aus, als wäre es schon ein paar Mal geschüttelt worden. Auf dem Kärtchen steht:\n\nFür {name}, einen ganz besonderen Helden.", sourceObjectiveStatus = "unverified-source-field" }
quests[8789] = { id = 8789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperiale Qirajiwaffen", description = "Wir haben hier nicht ein Jahrtausend in völliger Untätigkeit verbracht, {name}. Wir sahen mit eigenen Augen, wie sich diese Biester an ihren eigenen Artgenossen gütlich taten, nachdem diese ihre Nützlichkeit für den Schwarm verloren hatten. Wir lauschten, als sie ihre Pläne schmiedeten, diese Welt in Schutt und Asche zu legen. Und wir lernten, wie sich Verrat und Missgunst in ihren Reihen ausbreiten.\n\nSie haben Schwächen und wir wissen nun, wie wir diese zu unserem Vorteil nutzen können.\n\nFindet und bringt mir ihre Zeremonienwaffen. Zusammen, mit dem durch ihren Gott erschaffenen Element, werden wir daraus mächtige Instrumente der Zerstörung erschaffen.", sourceObjective = "Arygos im Tempel von Ahn'Qiraj wird Euch mit Elementium erfüllte Ausrüstung herstellen, wenn Ihr ihm imperiale Qirajiwaffen und 3 Einheiten Elementiumerz bringt.", progress = "Findet, worum ich Euch gebeten habe und Ihr werdet weit mehr als nur die Summe Eurer Teile werden, großer Held.", completion = "Jetzt, da diese Waffen mit Elementium erfüllt sind, werden sie sich mit Leichtigkeit durch jeden Qiraji und ihren Gott schneiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[8790] = { id = 8790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperiale Qirajiinsignien", description = "Arygos hat die Theorie aufgestellt, dass das Element, welches während des Konflikts zwischen den uralten Göttern und ihren Anhängern entstanden ist, unter den richtigen Bedingungen für sie tödlich ist. Ich spreche vom Elementium, <Sterblicher/Sterbliche>.\n\nFindet und bringt mir imperiale Qirajiinsignien sowie das giftige Element, dann werde ich Euch Waffen von größter Macht erschaffen!", sourceObjective = "Merithra des Traums im Tempel von Ahn'Qiraj wird Euch mit Elementium erfüllte Ausrüstung herstellen. Bringt ihr dazu imperiale Qirajiinsignien und 3 Einheiten Elementiumerz.", progress = "Ihr werdet sie niederstrecken und uns von diesen Fesseln befreien.", completion = "Nutzt diesen Gegenstand weise, {name}. Lasst sie den Schmerz ihrer Opfer am eigenen Leib erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[8791] = { id = 8791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Untergang von Ossirian", description = "Eine schreckliche Bedrohung hat ihr Ende gefunden. Der grausame Ossirian existiert nicht mehr.\n\nDie Bewohner Kalimdors werden aufatmen, wenn sie von diesem glorreichen Sieg erfahren. Nehmt Ossirians Kopf und bringt ihn zu Kommandant Mar'alith auf Burg Cenarius.", sourceObjective = "Bringt den Kopf von Ossirian dem Narbenlosen zu Kommandant Mar'alith auf Burg Cenarius in Silithus.", progress = "Ah, {name}. Wie ich sehe, seid Ihr zurückgekehrt und sogar in einem Stück! Welche Neuigkeiten bringt Ihr aus Ahn'Qiraj?", completion = "Ich entbiete Euch meine höchste Anerkennung und erlaube es Euch, einen Gegenstand von höchster Macht auszuwählen, {name}! Ihr habt den Bewohnern von Kalimdor einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8792] = { id = 8792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht Euch!", description = "Hallo, schön das Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Horde braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Horde braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, {name}! Wir brauchen Eure Unterstützung!\n\nAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Kriegsherr Gorchuk. Können wir auf Euch zählen, {class}? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?", sourceObjective = "Sprecht mit Kriegsherr Gorchuk im Tal der Geister in Orgrimmar.", completion = "Throm'ka, {class}! Es ist schön zu sehen, dass Ihr uns in dieser dunklen Stunde zur Seite steht, {name}! So viele Mitglieder der Horde haben sich bereits freiwillig verpflichtet, uns bei den Vorbereitungen für den aufziehenden Krieg in Ahn'Qiraj zu unterstützen. Unsere Anstrengungen hier, werden der Garant für den Sieg über die Silithiden und Ihre dunklen Meister sein!\n\nNun, jetzt da Ihr hier seid, solltet Ihr Euch mit den örtlichen Sammlern unterhalten und sehen, welche Materialien Ihr am besten beschaffen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8793] = { id = 8793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht Euch!", description = "Hallo, schön das Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Horde braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Horde braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, {name}! Wir brauchen Eure Unterstützung!\n\nAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Kriegsherr Gorchuk. Können wir auf Euch zählen, {class}? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?", sourceObjective = "Sprecht mit Kriegsherr Gorchuk im Tal der Geister in Orgrimmar.", completion = "Throm'ka, {class}! Es ist schön zu sehen, dass Ihr uns in dieser dunklen Stunde zur Seite steht, {name}! So viele Mitglieder der Horde haben sich bereits freiwillig verpflichtet, uns bei den Vorbereitungen für den aufziehenden Krieg in Ahn'Qiraj zu unterstützen. Unsere Anstrengungen hier, werden der Garant für den Sieg über die Silithiden und Ihre dunklen Meister sein!\n\nNun, jetzt da Ihr hier seid, solltet Ihr Euch mit den örtlichen Sammlern unterhalten und sehen, welche Materialien Ihr am besten beschaffen könnt.", sourceObjectiveStatus = "unverified-source-field" }
