quests[8818] = { id = 8818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Belobigungsabzeichen", progress = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf in Thunder Bluff ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf in Thunder Bluff würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", completion = "Sehr gut! Eure glorreichen Taten wurden verzeichnet und Ihr habt Eure verdiente Anerkennung erhalten. Macht so weiter, {class}!\n\nIch stehe Euch auch in Zukunft zur Verfügung, falls Ihr weitere Abzeichen abgeben möchtet." }
quests[8819] = { id = 8819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehn Belobigungsabzeichen", progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe Ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf in Darnassus sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf in Darnassus nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", completion = "Hervorragend! Ihr musstet so einiges auf Euch nehmen, um diese Abzeichen zu erhalten. Von jetzt an wird man Euch eine Menge Respekt entgegen bringen! Wie es sich für Eure großartige Pflichterfüllung und Hingabe gehört! Es sind Abenteurer von Eurem Kaliber, {name}, die etwas in der Welt bewirken!\n\nLasst es mich wissen, wenn Ihr noch weitere Abzeichen zur Hand habt. Ich werde sie gerne entgegennehmen." }
quests[8820] = { id = 8820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehn Belobigungsabzeichen", progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe Ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf bei den Gnomereganverbannten sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf bei den Gnomereganverbannten nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", completion = "Hervorragend! Ihr musstet so einiges auf Euch nehmen, um diese Abzeichen zu erhalten. Von jetzt an wird man Euch eine Menge Respekt entgegen bringen! Wie es sich für Eure großartige Pflichterfüllung und Hingabe gehört! Es sind Abenteurer von Eurem Kaliber, {name}, die etwas in der Welt bewirken!\n\nLasst es mich wissen, wenn Ihr noch weitere Abzeichen zur Hand habt. Ich werde sie gerne entgegennehmen." }
