quests[8856] = { id = 8856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wüstenüberlebenspaket", description = "Seitdem ständig neue Rekruten auf Burg Cenarius eintreffen, stehen wir vor dem Problem, sie in der Wüste am Leben zu erhalten. Der ständige Wasserentzug und die zahlreichen giftigen Kreaturen in dieser Gegend sind eine ernstzunehmende Gefahr für die unerfahren Soldaten. Sammelt alles, was notwendig ist, um ein Wüstenüberlebenspaket zusammenzustellen und bringt die erforderlichen Vorräte zu Calandrath auf Burg Cenarius.", sourceObjective = "Bringt 4 Kugeln des Wassers, 4 mächtige Gegengifte und 4 gebackene Lachse zu Calandrath in der Taverne von Burg Cenarius in Silithus.", sourceObjectiveStatus = "unverified-source-field" }
quests[8857] = { id = 8857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Kolosses - Ashi", description = "Ich suche nach schlachterprobten Abenteurern, die für mich eine Fragmentprobe vom Koloss des Ashischwarms zu Oglethorpe in Booty Bay bringen. Nein, nein, Ihr braucht Euch nicht einmal in die Nähe dieses Giganten zu wagen. Nehmt einfach eine von meinen Proben und beeilt Euch. Verrottet nutzt sie Onglethorpe nicht viel!", sourceObjective = "Bringt das Fragment vom Koloss des Ashischwarms zu Oglethorpe Obnoticus in Booty Bay.", progress = "Ja? Was habt Ihr für mich?", completion = "Oh, was für tolle Hühnchen ich aus diesem wundervollen Fragment basteln werde! Vielen Dank, mein Junge!", sourceObjectiveStatus = "unverified-source-field" }
quests[8858] = { id = 8858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Kolosses - Regal", description = "Ich würde nichts lieber tun, als Oilfist dieses verdammte Fragment in sein fettes Maul zu stopfen. Stattdessen stecke ich hier fest und sammle Proben von dieser zu groß geratenen Kakerlake! In Anbetracht ihrer Größe, werde ich hier wohl noch eine Weile beschäftigt sein.\n\nNehmt diese Probe und bringt sie für mich zu Oilfist... und beeilt Euch, {class}. Er zahlt auch sehr gut!\n\nAlso, ab zur Thoriumspitze in die sengende Schlucht.", sourceObjective = "Bringt das Fragment vom Koloss des Regalschwarms zu Aufseher Oilfist in die sengenden Schlucht.", completion = "Hervorragend! Aus diesem Chitinfragment können wir sicherlich einige sehr mächtige Rüstungen herstellen. Hier ist Eure Belohnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[8859] = { id = 8859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Kolosses - Zora", description = "Meine Leute hätte es beinahe erwischt, als sie diese Probe beschafft haben. Ihr müsst Euch unbedingt beeilen! Lord Maxwell Tyrosus wartet bereits voller Ungeduld auf eine frische Fragmentprobe. Er geht davon aus, dass uns die Geheimnisse dieses Kolosses im Kampf gegen die Geißel sehr von Nutzen sein werden!\n\nWieso seid Ihr noch hier!? Zur Hoffnung des Lichts! Ja, ja, man wird Euch für diese Aufgabe großzügig entlohnen...", sourceObjective = "Bringt das Fragment vom Koloss des Zoraschwarms zu Lord Maxwell Tyrosus an der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern.", progress = "Ihr seht ein wenig schwerfällig aus, mein Freund.", completion = "Exzellent und genau zur rechten Zeit! Gut gemacht, Junge.", sourceObjectiveStatus = "unverified-source-field" }
quests[8860] = { id = 8860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neujahrsfeier!", description = "In Stormwind wird das neue Jahr ganz groß gefeiert! Den ganzen Tag lang gibt es kostenlos was Hochprozentiges zu trinken und nachts eine fantastische Feuerwerksschau! Das wird sicherlich ein Riesenspaß… allerdings findet auch in Booty Bay eine Neujahrsfeier statt. Ich wette, dort ist noch viel mehr los!\n\nEgal! Jedenfalls braucht Gastwirtin Allison eine Ladung Kokelwälder Festtagsspeisen, um alle Partylöwen satt in das neue Jahr zu bringen. Würdet Ihr mir den Gefallen tun und die Vorräte für mich abliefern?\n\nDanke, {name}! Ihr findet Gastwirtin Allison in der Taverne zur güldenen Rose, drüben im Handelsdistrikt von Stormwind.", sourceObjective = "Bringt die Vorräte von Kokelwälder zu Gastwirtin Allison in Stormwind.", progress = "Hallo! Seid Ihr wegen der Party hier? Oder wollt Ihr nur ein wenig Eure müden Füße ausruhen?", completion = "Oh, meine Vorräte von Kokelwälder! Großartig! Die brauche ich dringend, um all die hungrigen Mäuler während der Feierlichkeiten zu stopfen!\n\nVielen Dank für Eure Hilfe, {name}. Bitte, nehmt dies als Belohnung an und vergesst nicht mit den anderen draußen zu trinken und zu tanzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[8861] = { id = 8861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neujahrsfeier!", description = "In Thunder Bluff wird das neue Jahr ganz groß gefeiert! Den ganzen Tag lang gibt es kostenlos was Hochprozentiges zu trinken und nachts eine fantastische Feuerwerksschau! Das wird sicherlich ein Riesenspaß… allerdings findet auch in Booty Bay eine Neujahrsfeier statt. Ich wette, dort ist noch viel mehr los!\n\nEgal! Jedenfalls braucht Gastwirtin Pala eine Ladung Kokelwälder Festtagsspeisen, um alle Partylöwen satt in das neue Jahr zu bringen. Würdet Ihr mir den Gefallen tun und die Vorräte für mich abliefern?\n\nDanke, {name}! Ihr findet Gastwirtin Pala in der Taverne nahe der Brücke zur Anhöhe der Jäger.", sourceObjective = "Bringt die Vorräte von Kokelwälder zu Gastwirtin Pala in Thunder Bluff.", progress = "Guten Tag, {class}! Seid Ihr wegen den Feierlichkeiten nach Thunder Bluff gekommen? Oder wollt Ihr nur ein wenig Eure von der Jagd müden Hufe ausruhen?", completion = "Oh, sehr gut! Mit diesen Vorräten sollte ich alle Feiernden auf dem Neujahrsfest bewirten können!\n\nIch danke Euch, {name}. Ich stehe in Eurer Schuld. Bitte, nehmt diese Münzen als Dankeschön... und befolgt meinen Rat - nehmt einen herzhaften Schluck aus dem Fass draußen und schließt Euch den anderen beim Feiern des neuen Jahres an!", sourceObjectiveStatus = "unverified-source-field" }
quests[8862] = { id = 8862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Kerze", progress = "Elunes Kerze ist für die Anhänger des Mondfests ein Artefakt der großen Verehrung. Die Kerze beinhaltet wahres Mondlicht, bereit zur Freigabe!\n\nDieses Licht ist für die meisten Kreaturen harmlos, aber Ihr werdet sehen, dass Omen und seine Diener davon Verbrennungen erleiden und geblendet werden.", completion = "Nun gut - ich akzeptiere diese Münzen der Urahnen. Bitte nehmt Elunes Kerze mit meinen besten Wünschen. Erfreut Euch auch an diesem zusätzlichen Feuerwerk.\n\nMöge Euer Mondfest freudig und voller Heiterkeit sein, {name}.\n\nMöchtet Ihr Euch Omen und seinen Dienern wirklich stellen, so werdet Ihr Elunes Kerze recht nützlich finden..." }
quests[8863] = { id = 8863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festtagsklöße", progress = "Wenn Ihr hungrig seid, dann solltet ihr zu der richtigen Adresse kommen!\n\nKlöße sind das traditionelle Gericht des Mondfests; man serviert es bereits seit den Zeiten des ersten Mondfests und ich bin stolz, dass ich diese Köstlichkeit während der diesjährigen Feierlichkeiten anbieten kann. Im Austausch gegen eine einzige Münze der Urahnen werde ich Euch von einer Probe dieses unvergleichlich genüsslichen Gerichts kosten lassen!", completion = "Ausgezeichnet - bitte genießt diese Klöße mit meinen besten Wünschen. Auch wenn sie nur ein kleines Zeichen der Anerkennung für Eure Ehre sind, die Ihr Euch mittels Eurer Taten verdient habt, so denke ich doch, dass Ihr sie alle gleichermaßen genießen werdet.\n\nSolltet Ihr noch mehr Münzen der Urahnen besitzen, so bin ich gewillt Euch ein reiches Angebot an Gegenständen im Austausch dafür anzubieten." }
quests[8864] = { id = 8864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festtagskleider des Mondfests", progress = "Ich habe eine Auswahl an Kleidern, die Euch interessieren könnte. Derartige Gewänder wurden in vergangenen Zeiten während des Mondfests getragen. Die Auswahl, die ich heute zu bieten habe, ist vielleicht die beste, die ich jemals gesehen habe. Jedes Stück ist aus den feinsten und geschmeidigsten Materialien handgefertigt worden.\n\nIch lasse Euch im Tausch gegen ein paar Münzen der Urahnen unter den drei Kleidungsstilen einen für Euch selbst auswählen. Ist das annehmbar für Euch?", completion = "Nun gut - ich akzeptiere diese Münzen der Urahnen. Bitte nehmt dieses Kleid mit meinen besten Wünschen. Erfreut Euch auch an diesem zusätzlichen Feuerwerk.\n\nDa Ihr unsere Urahnen geehrt habt, ehrt Ihr mich mit Eurer bloßen Anwesenheit. Ich danke Euch, möge Euer Mondfest freudig sein." }
quests[8865] = { id = 8865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festliche Hosenanzüge des Mondfests", progress = "Ich freue mich Euch mitteilen zu können, dass ich über eine feine Auswahl an festlichen Hosenanzügen verfüge, die ich Euch anbieten kann... aber nur im Tausch gegen Münzen der Urahnen. Wenn Ihr Wert auf Eure Erscheinung legt, dann ist dies genau das Richtige für Euch! Ich kann Euch versichern, dass Ihr keine vergleichbaren Hosenanzüge finden werdet.\n\nIch lasse Euch im Tausch gegen ein paar Münzen der Urahnen unter den drei Kleidungsstilen einen für Euch selbst auswählen. Ist das annehmbar für Euch?", completion = "Nun gut - ich akzeptiere diese Münzen der Urahnen. Bitte nehmt diesen Hosenanzug mit meinen besten Wünschen. Erfreut Euch auch an diesem zusätzlichen Feuerwerk.\n\nSolltet Ihr noch mehr Münzen der Urahnen zum Tauschen haben, dann sprecht noch einmal mit mir. Ich habe während des gesamten Mondfests zahlreiche Gegenstände in meinem Angebot." }
quests[8866] = { id = 8866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Bronzebeard", sourceObjective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, {name}. Nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[8867] = { id = 8867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondfeuerwerk", description = "Die Druiden von Moonglade feiern jedes Jahr den großen Triumph unserer Stadt über ein uraltes Übel.\n\nWir ehren die Weisheit unserer Urahnen, nehmen an herrlichen Festgelagen teil und... schießen natürlich Feuerwerk ab!\n\nFür eine kleine Spende könnt Ihr bei unserem Verkäufer farbenfrohe Raketen erwerben. Versucht doch mal einen der hier herumstehenden Zünder, {name}.", sourceObjective = "Zündet 8 Raketen und 2 Raketenbündel und kehrt dann zu einer Botin des Mondfests in irgendeiner Hauptstadt zurück.", progress = "Konntet Ihr die Zünder finden, {name}?", completion = "Gut gemacht, {name}.\n\nDa Ihr jetzt in der richtigen Stimmung seid, nehmt doch diese Einladung zu dem Fest in Moonglade an.\n\nEs sind recht unterhaltsame Feierlichkeiten, falls Ihr etwas Zeit haben solltet. Wir teilen dort miteinander gutes Essen, Getränke, Geschichten und natürlich... noch mehr Feuerwerk!\n\nÖffnet die Einladung, während Ihr innerhalb des Mondlichtkreises steht und Ihr werdet nach Moonglade transportiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[8868] = { id = 8868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Segen", description = "Das Biest Omen war einstmals ein bekannter Held. Als ein Wolf von großer Stärke und Geschicklichkeit, kämpfte er im Krieg der Urtume Seite an Seite mit den Helden dieser Zeit, bis er den dämonischen Mächten verfiel. Sein Hass richtete sich gegen seine einstigen Verbündeten und auf seinem Rachefeldzug durch Azeroth verbreitete er Tod und Verderben.\n\nLetztlich besiegte man ihn hier, in Moonglade, wo er bis heute auf dem Grund des Elune'ara Sees ruht. Doch jedes Jahr, während des Neujahrfests, erwacht er zu neuem Leben...\n\nSchart Eure Freunde um Euch! Zieht los, beschwört und besiegt das Biest Omen. Erlangt Elunes Segen!", sourceObjective = "Beschwört Omen, besiegt ihn und erlangt Elunes Segen. Kehrt anschließend zu Valadar Starsong in Nighthaven zurück.", progress = "Tief, tief im Elune'ara See lauert Omen, {name}...", completion = "Das habt Ihr sehr gut gemacht, {name}. Der Sieg über Omen hat seinen Geist wieder in die Tiefen des Elune'ara Sees verbannt. Obwohl das Biest durch Elune selbst gesegnet wurde und es dadurch unsterblich ist, wird sein Zorn für ein weiteres Jahr besänftigt sein.\n\nEuer Sieg ist eine Feier, {name} – eine Feier zu Ehren der Macht Omens, Eurer Stärke und der Ausdauer Eurer Verbündeten und nicht zuletzt des Friedens, den Ihr diesem tragischen Held der Vergangenheit geschenkt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8869] = { id = 8869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süße Beschaulichkeit", description = "In den Grenzen der Scharlachroten Bastion liegt die süße Beschaulichkeit. Der purpurrote Hammerschmied bewacht das Rezept mit seinem Leben. Besiegt ihn und bringt mir seine Schürze. Dafür werde ich Euch zu einem Hammerschmied ausbilden.\n\nIhr müsst eines wissen: Wenn Ihr Euch für den Weg des Hammerschmieds entschieden habt, sind die Wege des Schwertschmieds und des Axtschmieds nicht mehr verfügbar.", sourceObjective = "Begebt Euch nach Stratholme und tötet den purpurroten Hammerschmied. Nehmt die Schürze des purpurroten Hammerschmiedes und kehrt zu Lilith zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8870] = { id = 8870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder soweit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns, das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests im Mystikerviertel von Ironforge. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8871] = { id = 8871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder soweit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns, das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests im Parkviertel von Stormwind. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8872] = { id = 8872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder soweit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns, das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests in der Enklave des Cenarius in Darnassus. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8873] = { id = 8873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder soweit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns, das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests im Tal der Weisheit in Orgrimmar. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8874] = { id = 8874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder soweit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns, das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests am Eingang zur Undercity. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8875] = { id = 8875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder soweit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns, das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests auf der Anhöhe der Ältesten in Thunder Bluff. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8876] = { id = 8876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine Raketen", progress = "Ich hüte das Geheimnis zur Herstellung der Mondfestraketen und freue mich, mein Wissen mit den Würdigen zu teilen.\n\nIch kann Euch im Tausch gegen Münzen der Urahnen das Rezept zur Herstellung einer kleinen Rakete anbieten...", completion = "Ah, sehr schön. Hier ist Euer Rezept, {name}, möge Elune Euch segnen." }
quests[8877] = { id = 8877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zünder für Feuerwerk", progress = "Auch wenn Raketen wunderbar zum Feiern sind, so müssen sie doch von einem richtigen Zünder abgefeuert werden, damit man ihre wahre Herrlichkeit sehen kann...\n\nBringt mir Münzen der Urahnen und ich lehre Euch die Herstellung von Feuerwerkszündern, wie man sie in Moonglade sieht.", completion = "Da seid Ihr ja, {name}. Hier ist der Bauplan zur Herstellung von Feuerwerkszündern. Platziert die Zünder dort, wo Ihr feiern möchtet, und ladet Eure Freunde dazu ein!" }
quests[8878] = { id = 8878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festtagsrezepte", progress = "Die Kleider und Hosenanzüge, die Ihr hier sehen könnt, sind traditionelle Gewänder vergangener Zeiten. Sie werden zu Ehren alter Gebräuche und geliebter Vorfahren getragen.\n\nBringt Ihr mir Münzen der Urahnen, {name}, werde ich Euch das Muster zur Herstellung traditioneller roter Kleider oder Hosenanzüge geben.", completion = "Hier sind die Muster, {name}. Ich bin mir sicher, dass Ihr die Ergebnisse dieses Herstellungsgeheimnisses wunderschön finden werdet." }
quests[8879] = { id = 8879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Raketen", progress = "Große Festtagsraketen erhellen den Himmel sternengleich - nur die Raketenbündel können mit ihrer Schönheit rivalisieren!\n\nBringt mir Münzen der Urahnen und ich lehre Euch ihre Herstellung.", completion = "Nun gut - ich akzeptiere diese Münzen der Urahnen. Hier ist Euer Rezept, {name}. Verwendet sie, um Elunes Herrlichkeit zu verbreiten!" }
quests[8880] = { id = 8880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raketenbündel", progress = "Raketenbündel bestehen aus einer Anzahl unterschiedlicher Raketen. Ihre Schönheit ist überwältigend! Bringt mir Münzen der Urahnen und ich werde das Wissen ihrer Herstellung mit Euch teilen…", completion = "Bitte sehr, {name}. Nehmt diesen Bauplan und erlernt seine Geheimnisse. Ich wünsche Euch alles Gute und freue mich schon auf Eure Kreationen!" }
quests[8881] = { id = 8881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Raketenbündel", progress = "Die Herstellung großer Raketenbündel erfordert viel Erfahrung und noch mehr Ressourcen, doch ihre Schönheit ist die Mühen wert! Bringt mir Münzen der Urahnen und ich werde das Wissen ihrer Herstellung mit Euch teilen.", completion = "Vielen Dank, {name}. Hier ist der Bauplan zur Herstellung von großen Raketenbündeln. Möge Euer Feuerwerk allen Zuschauern viel Freude und Glück bereiten." }
quests[8882] = { id = 8882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zünder für Raketenbündel", progress = "Die schönsten Feuerwerke erfordern ganze Bündel an Feuerwerksraketen! Um diese abzufeuern, benötigt man Zünder für Raketenbündel! Wäre es dann nicht logisch für Euch, wenn Ihr das Geheimnis der Herstellung solcher Zünder von mir erlernen würdet? Bringt mir Münzen der Urahnen und ich werde mein Wissen mit Euch teilen…", completion = "Hier ist Euer Bauplan. Studiert ihn ausführlich und lernt…\n\nViel Glück, {name}. Mögen Eure Feuerwerke den Nachthimmel noch heller erleuchten, als die Feierlichkeiten des Mondfests selbst!" }
quests[8883] = { id = 8883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valadar Starsong", description = "Jetzt, da Ihr in Besitz der Mondfesteinladung seid, könntet Ihr doch einmal nach Moonglade reisen - Ihr werdet dort viele Feiernde vorfinden! In Nighthaven erwarten Valadar Starsong und seine Schwester Fariel bereits diejenigen, die die Feierlichkeiten kaum erwarten können.\n\nReist nach Moonglade mit Hilfe des Mondlichts und sprecht mit Valadar Starsong; schaut Euch um und erfahrt welche Preise Ihr während des Fests gewinnen könnt!", sourceObjective = "Verwendet die Mondfesteinladung im Mondlicht und reist somit nach Moonglade. Sprecht nach Eurer Ankunft in Nighthaven mit Valadar Starsong.", completion = "{name}, willkommen in Nighthaven, Gastgeber des Mondfests! Wenngleich unser Dorf normalerweise etwas entlegen und abgesondert von den Bewohner Azeroths liegt, so öffnen wir während der Festtage doch allen unsere Arme und Herzen.\n\nAmüsiert Euch gut, solange Ihr hier seid, {name}, und sprecht wieder mit mir oder meiner Schwester, wenn Ihr bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[8884] = { id = 8884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischköpfe, Fischköpfe...", description = "Seid gegrüßt, {class}. Was, frage ich Euch, könnt Ihr erkennen, wenn Ihr in Richtung Küste seht? Richtig, unser Strand... unsere Stille Küste wurde vom Übel, den Murlocs, befallen.\n\nDieser Makel darf nicht bestehen bleiben!\n\nIch habe eine Aufgabe für Euch. Solltet Ihr bereit dazu sein, so würde ich ihre Köpfe haben wollen! Mal sehen, ob wir ihre Zahl derart verringern können, dass sie nicht mehr anders können, als in die dunklen Tiefen zurückzukehren, aus denen sie gekommen sind!", sourceObjective = "Sammelt 8 Köpfe von Grimmschuppenmurlocs und bringt sie zu Hathvelion Sonnenblick im Immersangwald auf der Klippe, die die Stille Küste überblickt.", progress = "Wir Waldläufer von der Zuflucht der Weltenwanderer haben uns der Wiedergutmachung aller Schäden gewidmet, die unser schönes Land so schrecklich verheert haben. Egal, wie lange es auch dauern mag.\n\nIch kann mich doch darauf verlassen, dass Ihr mit den Murlocköpfen zurückgekehrt seid, die ich von Euch verlangt habe?", completion = "Gute Arbeit, {class}. Dem Gestank nach zu urteilen, seid Ihr mit der von mir geforderten Beute zurückgekehrt, vielleicht sogar mit mehr. Ich bin mir sicher, dass wir dafür Verwendung haben werden, sei es in einem Eintopf oder etwas Ähnlichem.\n\nLeider scheinen Eure Bemühungen den Zweck nicht erfüllt zu haben; die Murlocs ziehen sich noch immer nicht zurück. Wir müssen noch tatkräftiger handeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[8885] = { id = 8885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mmmrrrgggllls Ring", description = "Die Grimmschuppenmurlocs haben sich durch Eure Taten nicht vertreiben lassen. Ich glaube aber zu wissen, was sie endlich in die Flucht schlagen wird, und wie ich mich gleichzeitig persönlich an ihnen rächen kann.\n\nSie haben einen Murlochäuptling, der sich selbst Mmmrrrggglll nennt. Er wandert entlang des Goldenen Strandes südlich der Flussmündung umher. Dies Biest hat einst einen meiner Kameraden getötet und trägt seitdem seinen Ring als offenes Zeichen der Verachtung und des Spotts.\n\nVernichtet Mmmrrrggglll und bringt mir den Ring meines Freundes wieder. Das sollte diese Monster ein für alle Mal einschüchtern!", sourceObjective = "Erlangt Mmmrrrgggllls Ring von dem Häuptling der Grimmschuppen und kehrt damit anschließend zu Hathvelion Sonnenblick im Immersangwald auf der Klippe, die die Stille Küste überblickt, zurück.", progress = "Ihr verhelft mir zu Erfolg und Rache, {class}. Habt Ihr den Ring?", completion = "Endlich! Die Grimmschuppen sind zwar noch immer nicht gewichen, wie erhofft, aber es war ein herrliches Schauspiel, als sie nach dem Tod ihres Anführers in Panik und Verwirrung umhergeirrt sind. Ihr habt meinen Dank und den der Sin'dorei von Silbermond!\n\nBitte, nehmt eine dieser Belohnungen für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
